fn byte_at(s: &[u8], i: usize) -> Option<u8> {
    let hi = hex_value(s[i]);
    let lo = hex_value(s[i + 1]);
    if hi > 15 || lo > 15 {
        None
    } else {
        Some(hi * 16 + lo)
    }
}

parse_color.kernel_code:
pub fn parse_color(s: &[u8]) -> Option<Rgb> {
    if s.len() != 7 || s[0] >= 0x80 {
        return None;
    }
    // (explicit matches rather than `?`: the same, and plain control flow
    // for the extraction)
    let r = match byte_at(s, 1) {
        Some(v) => v,
        None => return None,
    };
    let g = match byte_at(s, 3) {
        Some(v) => v,
        None => return None,
    };
    let b = match byte_at(s, 5) {
        Some(v) => v,
        None => return None,
    };
    Some(Rgb { r, g, b })
}

