hex_value.kernel_code:
pub fn hex_value(b: u8) -> u8 {
    if b >= 48 && b <= 57 {
        b - 48
    } else if b >= 97 && b <= 102 {
        b - 87
    } else if b >= 65 && b <= 70 {
        b - 55
    } else {
        16
    }
}
